"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7898],{51800:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"LoadingScreen","desc":"Replaces the default Roblox loading screen and covers the view until\\n`PreloadLib` has loaded every sound, animation, and texture/material the\\nclient can see.\\n\\nAssets come from two sources:\\n- Instances of `PRELOAD_CLASSES` under the replicated services (MeshParts\\n  give only their TextureID, so their meshes still stream in during play).\\n- Every `rbxassetid://` string inside the `Configs` modules (ids that only\\n  exist in code, such as SoundConfig SFX or TrainConfig animations).\\n\\nThe bar counts batches, not PreloadLib\'s per-asset `completed`: one\\ninstance can resolve several assets or none. It never stands still: it\\ncreeps toward JOIN_END while the place downloads (Roblox gives no progress\\nfor that), and a highlight sweeps across the fill the whole time.","realm":["Client"],"source":{"line":21,"path":"src/ReplicatedFirst/LoadingScreen.client.luau"}}')}}]);